private function checkValue(array $slot, string $value, array $params): void {
    $key=$slot['key'];
    $refuse=fn(string $code,string $message,array $extra=[])=>new ContractProblem($code,$message,$key,null,$extra);
    if (!empty($slot['requiresEvidence']) && $value!==$slot['sample']) {
        $evidence=$params['evidence'][$key]??null;
        if(!is_string($evidence)||trim($evidence)===''||strlen($evidence)>8000)throw $refuse('SLOT_EVIDENCE_REQUIRED','Customer evidence required: '.$key);
    }
    // Empty ACM fields control conditional markup; changing occupancy changes layout. The one
    // exception is the identity module: it renders nothing itself, and a fact the customer does
    // not have (a TikTok page, a legal name) must be emptied, or the demo's value is shown instead.
    if(empty($slot['siteIdentity'])) {
        if(trim($value)==='' && trim($slot['sample'])!=='')throw $refuse('SLOT_EMPTY_STATE','Content cannot remove an occupied slot: '.$key);
        if(trim($value)!=='' && trim($slot['sample'])==='')throw $refuse('SLOT_EMPTY_STATE','Content cannot activate an empty slot: '.$key);
    }
    if(preg_match('/[<>\x00-\x08\x0b\x0c\x0e-\x1f]/u',$value))throw $refuse('SLOT_NOT_CONTENT','Markup and control characters are not content: '.$key);
    if(IdentityTokens::hasDirective($value))throw $refuse('SLOT_NOT_CONTENT','Joomla plugin directives are not content: '.$key);
    // An imported site stores links and pictures in whatever form it grew; a quickstart's rules below
    // were written for the forms its own profile ships, and stay exactly as they are. A derived
    // slot's length limit is sized from its old words, which says nothing about a link or a file
    // name; an address has its own ceiling instead.
    if($this->derivedMode && in_array($slot['type'],['url','image'],true)) {
        if(strlen($value)>self::DERIVED_LINK_BYTES)throw $refuse('SLOT_TOO_LONG','Content too long: '.$key,['limit'=>self::DERIVED_LINK_BYTES,'actual'=>strlen($value)]);
        $this->checkDerivedLink($slot,$value,$refuse); return;
    }
    if(mb_strlen($value)>$slot['maxCharacters'])throw $refuse('SLOT_TOO_LONG','Content too long: '.$key,['limit'=>(int)$slot['maxCharacters'],'actual'=>mb_strlen($value)]);
    // Slot fit (ADR 0039), only on a slot that carries one and never against its own demo value.
    $fit=SlotFit::of($slot);
    if($fit!==null&&SlotFit::restores($slot,$value))$fit=null;
    if($fit!==null&&$slot['type']==='text')SlotFit::checkText($fit,$key,$value,$refuse);
    if($slot['type']==='url' && (strpos($value,'//')===0 || strpos($value,'\\')!==false))throw $refuse('SLOT_LINK_UNSUPPORTED','Unsupported CTA URL: '.$key);
    if($slot['type']==='url'&&$value!==''&&!preg_match('~^(https://[^\s]+|mailto:[^\s]+|tel:[+0-9 ()-]+|index\.php\?Itemid=[0-9]+|/[a-zA-Z0-9/_?&=.%#-]*|#[a-zA-Z0-9_-]+)$~D',$value))throw $refuse('SLOT_LINK_UNSUPPORTED','Unsupported CTA URL: '.$key);
    if($slot['type']==='image'&&$value!=='') {
        if($fit!==null)SlotFit::checkKept($fit,$key,$params,$refuse);
        if(!preg_match('~^images/[a-zA-Z0-9/_-]+\.(png|jpe?g|webp)$~D',$value)||!is_file($this->root.'/'.$value))throw $refuse('SLOT_IMAGE_INVALID','Image must already exist in the site media library: '.$key);
        $resolved=realpath($this->root.'/'.$value);$imageRoot=realpath($this->root.'/images');
        if(!$resolved||!$imageRoot||strpos($resolved,$imageRoot.DIRECTORY_SEPARATOR)!==0)throw $refuse('SLOT_IMAGE_INVALID','Image escapes the site media library: '.$key);
        // the slot's own picture is stored as Joomla writes media values (`images/a.png#joomlaImage://local-images/a.png?width=…`):
        // read whole, it named no file, its shape was never known, and every shape was taken
        $before=@getimagesize($this->root.'/'.self::imagePath((string)$slot['sample']));$after=@getimagesize($this->root.'/'.$value);
        if(!$after||!$after[0]||!$after[1])throw $refuse('SLOT_IMAGE_INVALID','Image aspect ratio does not match its slot');
        // A fit that names the box's aspect holds the picture to it; without one, the demo file's shape decides, as always.
        if($fit!==null&&SlotFit::checkPicture($fit,$key,$after,$before,$this->root.'/'.$value,$refuse))return;
        if($before&&abs($before[0]/$before[1]-$after[0]/$after[1])>0.02)throw $refuse('SLOT_IMAGE_INVALID','Image aspect ratio does not match its slot');
    }
}
private function checkDerivedLink(array $slot, string $value, callable $refuse): void {
    $key=$slot['key'];
    if($value==='')return;
    if($slot['type']==='url') {
        if(strpos($value,'//')===0||strpos($value,'\\')!==false||!preg_match('~^(https?://\S+|mailto:\S+|tel:[+0-9 ()-]+|index\.php\?\S*|/\S*|#[a-zA-Z0-9_-]+)$~D',$value))
            throw $refuse('SLOT_LINK_UNSUPPORTED','Unsupported CTA URL: '.$key);
        return;
    }
    $path=self::imagePath($value);
    if(!preg_match('~^images/[^\s?#\\\\]+\.(png|jpe?g|webp|gif|avif|svg)$~iD',$path)||!is_file($this->root.'/'.$path))throw $refuse('SLOT_IMAGE_INVALID','Image must already exist in the site media library: '.$key);
    $resolved=realpath($this->root.'/'.$path);$imageRoot=realpath($this->root.'/images');
    if(!$resolved||!$imageRoot||strpos($resolved,$imageRoot.DIRECTORY_SEPARATOR)!==0)throw $refuse('SLOT_IMAGE_INVALID','Image escapes the site media library: '.$key);
}
private static function imagePath(string $value): string { return ltrim(explode('#',$value,2)[0],'/'); }
private function currentValue(array $row, array $slot, array &$parsed = []): string {
    $column=$slot['column'];$value=$row[$column];
    if(($slot['leaf']??null)!==null) {
        try { return LeafCodec::get((string)$value,$slot['leaf']); }
        catch (LeafCodecError $e) { throw new ContractProblem('SLOT_UNWRITABLE','Content slot is missing from its column: '.$slot['key'].' ('.$e->getMessage().')',$slot['key']); }
    }
    if(isset($slot['jsonPath'])) {
        $outer=$parsed['json'][$column] ??= json_decode($value,true,512,JSON_THROW_ON_ERROR);
        $value=isset($slot['nestedJson'])
            ? ($parsed['nested'][$column][$slot['nestedJson']] ??= json_decode($outer[$slot['nestedJson']],true,512,JSON_THROW_ON_ERROR))
            : $outer;
        foreach($slot['jsonPath'] as $key)$value=is_array($value)&&array_key_exists($key,$value)?$value[$key]:null;
        if(isset($slot['xpath'])) {
            if(!is_string($value))throw new RuntimeException('Content slot is not text');
            $nodes=(new DOMXPath(ContentSlots::html($value)))->query($slot['xpath']);
            if(!$nodes || $nodes->length!==1)throw new RuntimeException('Content slot is missing or ambiguous');
            return ContentSlots::slotText($nodes->item(0));
        }
    }
    elseif(isset($slot['xpath'])) {
        $nodes=($parsed['dom'][$column] ??= new DOMXPath(ContentSlots::html($value)))->query($slot['xpath']);
        if(!$nodes || $nodes->length!==1)throw new RuntimeException('Content slot is missing or ambiguous');
        return ContentSlots::slotText($nodes->item(0));
    }
    if(!is_string($value))throw new RuntimeException('Content slot is not text');
    return $value;
}
private function changeRow(array $row, array $slots, array $values): array {
    $html=[]; $json=[];
    foreach ($slots as $slot) {
        if (!array_key_exists($slot['key'],$values)) continue;
        $value=$values[$slot['key']]; $col=$slot['column'];
        // A derived slot names its leaf inside the column (LeafCodec): every layer is re-encoded
        // in its own format, and a value that would not read back is refused, never stored.
        if (($slot['leaf'] ?? null) !== null) {
            try { $row[$col]=LeafCodec::set((string)$row[$col],$slot['leaf'],(string)$value); }
            catch (LeafCodecError $e) { throw new ContractProblem('SLOT_UNWRITABLE','Content slot cannot be rewritten in place: '.$slot['key'].' ('.$e->getMessage().')',$slot['key']); }
        }
        // A JSON slot is a string at `jsonPath`, inside the nested JSON `nestedJson` names (an ACM's
        // `jatools-config`) or, without one, in the column's own JSON (an article's `images` and
        // `attribs`, a module's template fields, a menu item's page title). With `xpath` as well, that
        // string is HTML and the slot is one text or attribute in it (a textarea field holding markup).
        elseif (isset($slot['jsonPath'])) {
            $data=$json[$col]??json_decode($row[$col],true,512,JSON_THROW_ON_ERROR);
            $patch=static function(array $body) use ($slot,$value): array {
                if(!isset($slot['xpath']))return ContentSlots::jsonPatch($body,$slot['jsonPath'],$value);
                $leaf=$body; foreach($slot['jsonPath'] as $key){ if(!is_array($leaf)||!array_key_exists($key,$leaf))throw new RuntimeException('JSON slot is missing'); $leaf=$leaf[$key]; }
                if(!is_string($leaf))throw new RuntimeException('JSON slot is not text');
                return ContentSlots::jsonPatch($body,$slot['jsonPath'],ContentSlots::htmlPatch($leaf,[['xpath'=>$slot['xpath'],'value'=>$value]]));
            };
            if(isset($slot['nestedJson'])) {
                $inner=$slot['nestedJson']; $body=json_decode($data[$inner],true,512,JSON_THROW_ON_ERROR);
                $data[$inner]=json_encode($patch($body),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
            } else $data=$patch($data);
            $json[$col]=$data;
        }
        elseif (isset($slot['xpath'])) $html[$col][]=['xpath'=>$slot['xpath'],'value'=>$value];
        else $row[$col]=$value;
    }
    foreach($html as $col=>$changes)$row[$col]=ContentSlots::htmlPatch($row[$col],$changes);
    foreach($json as $col=>$data)$row[$col]=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    return $row;
}
